    if(frame.camera){yaw=frame.camera->GetVisualYawDegrees();pitch=frame.camera->HasElevationOverride()?frame.camera->GetElevationOverrideDegrees():34.0f;zoom=frame.camera->GetZoom();}
    const PlanetCommandCamera commandCamera{yaw,pitch,zoom};
    const float globeRadius=layout.globeRadius*std::clamp(zoom,.65f,1.35f);
    Rgba planetBase{.17f,.20f,.20f,.98f};
    if(command.planetType==PlanetType::Desert)planetBase={.42f,.29f,.15f,.98f};
    else if(command.planetType==PlanetType::Ice)planetBase={.34f,.50f,.58f,.98f};
    else if(command.planetType==PlanetType::Oceanic)planetBase={.10f,.30f,.48f,.98f};
    else if(command.planetType==PlanetType::Volcanic)planetBase={.34f,.12f,.08f,.98f};
    else if(command.planetType==PlanetType::Barren)planetBase={.24f,.22f,.20f,.98f};
    else if(command.planetType==PlanetType::GasGiant)planetBase={.38f,.29f,.20f,.98f};

    FilledCircle(layout.centerX,layout.centerY,0,globeRadius,planetBase,72);
    FilledCircle(layout.centerX-globeRadius*.18f,layout.centerY-globeRadius*.20f,0,globeRadius*.72f,
                 {std::min(1.0f,planetBase.r+.08f),std::min(1.0f,planetBase.g+.08f),std::min(1.0f,planetBase.b+.08f),.16f},64);
    Ring(layout.centerX,layout.centerY,0,globeRadius,{.26f,.66f,.70f,.72f},1.4f,72);

    const auto projected=PlanetaryCommandMapSystem::ProjectSelectable(command.industry,commandCamera,layout);
    if(command.commandOverlay==PlanetCommandOverlay::Logistics){
        for(std::size_t a=0;a<projected.size();++a){
            const auto ia=command.industry.hexes.find(projected[a].coord);if(ia==command.industry.hexes.end()||!ia->second.claimed)continue;
            for(std::size_t b=a+1;b<projected.size();++b){
                const auto ib=command.industry.hexes.find(projected[b].coord);if(ib==command.industry.hexes.end()||!ib->second.claimed)continue;
                const int dq=projected[a].coord.q-projected[b].coord.q,dr=projected[a].coord.r-projected[b].coord.r;
                const int ds=(-projected[a].coord.q-projected[a].coord.r)-(-projected[b].coord.q-projected[b].coord.r);
                if(std::max({std::abs(dq),std::abs(dr),std::abs(ds)})==1)Line(projected[a].x,projected[a].y,0,projected[b].x,projected[b].y,0,{.30f,.78f,.82f,.42f},1.4f);
            }
        }
    }
    for(const auto&p:projected){
        const auto it=command.industry.hexes.find(p.coord);if(it==command.industry.hexes.end())continue;const auto&h=it->second;
        const bool selected=PlanetaryCommandMapSystem::Same(p.coord,command.selectedHex);
        Rgba fill{.10f,.30f,.34f,.20f};
        if(command.commandOverlay==PlanetCommandOverlay::Resources)fill={.16f+.12f*h.resource,.34f+.42f*h.resource,.26f+.30f*h.resource,.28f+.34f*h.resource};
        else if(command.commandOverlay==PlanetCommandOverlay::Hazards)fill={.34f+.54f*h.hazard,.22f*(1.0f-h.hazard),.12f,.26f+.44f*h.hazard};
        else if(command.commandOverlay==PlanetCommandOverlay::Landing)fill=h.landingSite?Rgba{.72f,.62f,.18f,.58f}:Rgba{.10f,.22f,.24f,.18f};
        else if(command.commandOverlay==PlanetCommandOverlay::Development)fill=h.developed?Rgba{.24f,.72f,.46f,.62f}:h.claimed?Rgba{.16f,.46f,.42f,.42f}:Rgba{.10f,.22f,.24f,.16f};
        else if(h.developed)fill={.22f,.72f,.48f,.62f};else if(h.claimed)fill={.16f,.56f,.60f,.50f};else if(h.surveyed)fill={.20f,.42f,.46f,.28f};else if(p.frontier)fill={.12f,.28f,.32f,.12f};
        FilledCircle(p.x,p.y,0,p.radius,fill,6);
        const Rgba border=selected?Rgba{1.0f,.70f,.18f,.98f}:h.claimed?Rgba{.30f,.82f,.78f,.86f}:h.surveyed?Rgba{.30f,.60f,.64f,.58f}:Rgba{.22f,.46f,.50f,.34f};
        Ring(p.x,p.y,0,p.radius,border,selected?2.3f:h.claimed?1.5f:.9f,6);
        if(h.developed)FilledCircle(p.x,p.y,0,std::max(2.5f,p.radius*.18f),{.70f,.92f,.62f,.92f},8);
        if(h.landingSite&&(command.commandOverlay==PlanetCommandOverlay::Landing||selected))Ring(p.x,p.y,0,std::max(4.5f,p.radius*.34f),{1.0f,.82f,.28f,.88f},1.2f,4);
    }

    Line(layout.infoLeft,top+66,0,layout.infoLeft,bottom-16,0,{.10f,.34f,.40f,.56f},1.0f);
    const float ix=layout.infoLeft+22.0f;DrawText5x7("SELECTED SURFACE SECTOR",ix,top+84,.92f,{.62f,.82f,.84f,.90f});
    const auto selectedIt=command.industry.hexes.find(command.selectedHex);
    if(selectedIt!=command.industry.hexes.end()){
        const auto&h=selectedIt->second;const bool frontier=PlanetaryCommandMapSystem::IsFrontier(command.industry,h.coord);
        std::ostringstream coord;coord<<"["<<h.coord.q<<","<<h.coord.r<<"]";DrawText5x7(coord.str(),ix,top+112,1.08f,{1.0f,.76f,.30f,.96f});
        const char*state=h.developed?"DEVELOPED":h.claimed?"CLAIMED":h.surveyed?"SURVEYED":frontier?"FRONTIER":"UNKNOWN";
        DrawText5x7(std::string("STATE  ")+state,ix,top+142,.78f,{.54f,.78f,.80f,.86f});
        std::ostringstream a;a<<"RESOURCE  "<<static_cast<int>(h.resource*100)<<"%";DrawText5x7(a.str(),ix,top+166,.76f,{.48f,.76f,.62f,.84f});
        std::ostringstream b;b<<"HAZARD  "<<static_cast<int>(h.hazard*100)<<"%";DrawText5x7(b.str(),ix,top+188,.76f,{.84f,.50f,.34f,.84f});
        std::ostringstream c;c<<"BUILDABLE  "<<static_cast<int>(h.buildability*100)<<"%";DrawText5x7(c.str(),ix,top+210,.76f,{.54f,.72f,.76f,.84f});
        std::ostringstream d;d<<"DEVELOPMENT T"<<static_cast<int>(h.developmentTier);DrawText5x7(d.str(),ix,top+232,.76f,{.54f,.72f,.76f,.84f});
        DrawText5x7(h.landingSite?"LANDING SITE / CANDIDATE":"LANDING / NONE",ix,top+254,.76f,h.landingSite?Rgba{.94f,.76f,.30f,.90f}:Rgba{.42f,.54f,.56f,.72f});
        PlanetaryIndustrySystem pi;std::ostringstream inst;inst<<"INSTALLATIONS  "<<pi.InstallationsAt(command.industry,h.coord);DrawText5x7(inst.str(),ix,top+276,.76f,{.54f,.72f,.76f,.84f});
    }
    std::size_t claims=0,developed=0;for(const auto&kv:command.industry.hexes){claims+=kv.second.claimed?1u:0u;developed+=kv.second.developed?1u:0u;}
    std::ostringstream summary;summary<<"CLAIMS "<<claims<<"   DEVELOPED "<<developed<<"   INSTALLATIONS "<<command.industry.installations.size();DrawText5x7(summary.str(),ix,top+316,.72f,{.46f,.66f,.70f,.78f});
    DrawText5x7(command.commandStatus,ix,bottom-76,.70f,{.64f,.80f,.82f,.86f});
    DrawText5x7("LMB SELECT   RMB ORBIT   WHEEL ZOOM",left+22,bottom-50,.76f,{.50f,.72f,.76f,.86f});
    DrawText5x7("UP/DOWN SECTOR   F5 OVERLAY   ENTER SURVEY/CLAIM   SHIFT+ENTER INDUSTRIAL",left+22,bottom-28,.72f,{.50f,.72f,.76f,.86f});
}
